!function(){"use strict";var n=window.PGDash=window.PGDash||{};function e(){n.config=function(){var n=document.getElementById("pg_dash_config");if(!n)return null;try{return JSON.parse(n.textContent||"{}")}catch(n){return null}}()}n.config=null,n.renderers=n.renderers||{},n.register=function(e,t){n.renderers[e]=t},"loading"===document.readyState?document.addEventListener("DOMContentLoaded",e):e()}();
